   ],
   "source": "import numpy as np\n\n# Setup\nH, W = 64, 64\nimg = np.zeros((H, W, 3), dtype=np.uint8)\nimg[..., 0] = np.linspace(0, 255, W).astype(np.uint8)[None, :]   # R: left-to-right gradient\nimg[..., 1] = np.linspace(0, 255, H).astype(np.uint8)[:, None]   # G: top-to-bottom gradient\nimg[..., 2] = 128                                                  # B: constant\n\n# Task 2: Convert to grayscale\nweights = np.array([0.299, 0.587, 0.114])\ngray = np.dot(img.astype(np.float64), weights).astype(np.uint8)\n\n# Print requested values\nprint(f\"gray[0, 0]: {gray[0, 0]}\")\nprint(f\"gray[63, 63]: {gray[63, 63]}\")\nprint(f\"mean gray level: {gray.mean():.4f}\")\n"
