     "text": "Number of non-empty bins: 225\nFive most frequent gray levels and counts:\n  Gray level 111: count = 32\n  Gray level 140: count = 31\n  Gray level 104: count = 31\n  Gray level 162: count = 31\n  Gray level 90: count = 31\n"
    }
   ],
   "source": "import numpy as np\n\n# Setup\nH, W = 64, 64\nimg = np.zeros((H, W, 3), dtype=np.uint8)\nimg[..., 0] = np.linspace(0, 255, W).astype(np.uint8)[None, :]   # R: left-to-right gradient\nimg[..., 1] = np.linspace(0, 255, H).astype(np.uint8)[:, None]   # G: top-to-bottom gradient\nimg[..., 2] = 128                                                  # B: constant\nweights = np.array([0.299, 0.587, 0.114])\ngray = np.dot(img.astype(np.float64), weights).astype(np.uint8)\n\n# Task 4\nhist = np.bincount(gray.ravel(), minlength=256)\nnon_empty_bins = np.count_nonzero(hist)\nprint(f\"Number of non-empty bins: {non_empty_bins}\")\n\n# Five most frequent gray levels with their counts\ntop5_indices = np.argsort(hist)[::-1][:5]\nprint(\"Five most frequent gray levels and counts:\")\nfor level in top5_indices:\n    print(f\"  Gray level {level}: count = {hist[level]}\")\n"
