   "source": "import numpy as np\n\n# Setup\nH, W = 64, 64\nimg = np.zeros((H, W, 3), dtype=np.uint8)\nimg[..., 0] = np.linspace(0, 255, W).astype(np.uint8)[None, :]   # R: left-to-right gradient\nimg[..., 1] = np.linspace(0, 255, H).astype(np.uint8)[:, None]   # G: top-to-bottom gradient\nimg[..., 2] = 128                                                  # B: constant\nweights = np.array([0.299, 0.587, 0.114])\ngray = np.dot(img.astype(np.float64), weights).astype(np.uint8)\n\n# Task 5\nmask = gray > gray.mean()\nfg_count = np.sum(mask)\nfg_ratio = np.mean(mask)\n\nprint(f\"Foreground pixel count: {fg_count}\")\nprint(f\"Foreground pixel ratio: {fg_ratio:.4f}\")\n\n# Downsample to 8x8 blocks\nblock_h, block_w = H // 8, W // 8\nblocks = mask.reshape(8, block_h, 8, block_w).transpose(0, 2, 1, 3)\nblock_means = blocks.mean(axis=(2, 3))\n\nprint(\"Downsampled mask (8x8 ASCII art):\")\nfor row in block_means:\n    line = \"\".join(\"#\" if val > 0.5 else \".\" for val in row)\n    print(line)\n"
